{
  "гриб": "мухомор серо-розовый (Amanita rubescens)",
  "состав": [
    {
      "вещество": "рубесцин (rubescin)",
      "содержание": "неизвестно (белковая фракция, доля в сухом веществе не установлена точно)",
      "влияние": "Основной токсин вида, вызывает расстройство желудочно-кишечного тракта (тошнота, рвота, диарея) в течение 30–60 мин после приёма."
    },
    {
      "вещество": "мускарипн",
      "содержание": "≈0,01–0,05 % от сухого веса (значительно меньше, чем в A. muscaria)",
      "влияние": "Активирует мускариновые холинергические рецепторы, вызывает саливацию, брадикардию и бронхоспазм."
    },
    {
      "вещество": "аминокислоты (аланин, глутаминовая, аспарагиновая, глицин, лейцин, лизин и др.)",
      "содержание": "≈15–20 % от сухого веса",
      "влияние": "Обеспечивают пластический обмен и синтез белков в организме человека; сами по себе нетоксичны."
    },
    {
      "вещество": "β-глюканы и другие полисахариды",
      "содержание": "≈5–10 % от сухого веса",
      "влияние": "Стимулируют активность макрофагов и NK-клеток, оказывая модулирующее действие на иммунную систему."
    },
    {
      "вещество": "каротиноиды (ликопин, β-каротин, лютеин)",
      "содержание": "неизвестно (обеспечивают серо-розовое окрашение пластинок и руменица при ушибе)",
      "влияние": "Выступают антиоксидантами, нейтрализующими свободные радикалы в тканях."
    },
    {
      "вещество": "хитин",
      "содержание": "≈3–5 % от сухого веса (структурный компонент клеточной стенки)",
      "влияние": "Усваивается частично, стимулирует синтез короткоцепочечных жирных кислот в толстой кишке."
    },
    {
      "вещество": "фитиновая кислота (инозитогексафосфат)",
      "содержание": "≈2–4 % от сухого веса",
      "влияние": "Хелатирует Fe²⁺, Zn²⁺, Ca²⁺, снижая их биодоступность при избыточном поступлении."
    },
    {
      "вещество": "витамины группы B (B₁, B₂, B₅, B₆, B₉) и витамин С",
      "содержание": "мг/кг свежего веса (B₉ ≈ 30–60 мг/кг; C ≈ 10–20 мг/кг; остальные — следовые)",
      "влияние": "Участвуют в коферментных реакциях (окислительно-восстановительные процессы, синтез нуклеиновых кислот, антиоксидантная защита)."
    },
    {
      "вещество": "минеральные элементы (K, P, Ca, Fe, Mg, Zn, Cu)",
      "содержание": "≈3–5 % от сухого веса (K и P преобладают)",
      "влияние": "Поддерживают электролитный баланс, ферментативную активность и транспорт кислорода в крови."
    }
  ]
}

{
  "гриб": "Amanita caesarea (цезарский гриб, мухомор Цезаря, царский гриб)",
  "состав": [
    {
      "вещество": "Белки (аминокислоты: глутаминовая, аспарагиновая, глицин, аланин, лейцин, валин и др.)",
      "содержание": "~3–6 % от свежего веса (~20–30 % от сухого веса)",
      "влияние": "Служат источником незаменимых и заменимых аминокислот, необходимых для синтеза тканевых белков."
    },
    {
      "вещество": "Полисахариды и хитин (клеточная стенка)",
      "содержание": "~1–2 % от свежего веса",
      "влияние": "Хитин и β-глюканы обладают пребиотическим и умеренно иммуномодулирующим действием."
    },
    {
      "вещество": "Липиды (липоиды, фосфолипиды, стерины — эргостерол)",
      "содержание": "~0,1–0,3 % от свежего веса",
      "влияние": "Эргостерол под действием УФ-излучения превращается в витамин D₂, поддерживающий обмен кальция."
    },
    {
      "вещество": "Минеральные элементы (K, P, Mg, Ca, Fe, Zn, Cu, Se, Mn)",
      "содержание": "~0,3–0,5 % золы от свежего веса; K — до ~0,2 % от свежего веса, Se — следы (мкг/кг)",
      "влияние": "Поддерживают электролитный баланс, работу ферментов и антиоксидантную защиту (Se, Cu, Zn)."
    },
    {
      "вещество": "Витамины группы B (рибофлавин B₂, ниацин B₃, пантотеновая кислота B₅)",
      "содержание": "рибофлавин — ~0,2–0,4 мг/100 г свежего веса; ниацин — ~1–3 мг/100 г",
      "влияние": "Участвуют в окислительно-восстановительных реакциях и синтезе НДФА/НАДФА, поддерживая клеточный метаболизм."
    },
    {
      "вещество": "Циклопептидные токсины (α-аманицин, β-аманицин, мусцимола, фаллоидины)",
      "содержание": "отсутствуют (не обнаружены)",
      "влияние": "Отсутствие данных токсинов обусловливает отсутствие гепато- и нейротоксического действия, характерного для A. phalloides, и делает гриб пищевым."
    },
    {
      "вещество": "Органические кислоты (глутаминовая, лимонная, яблочная)",
      "содержание": "неизвестно (следовые количества, доли % от сухого веса)",
      "влияние": "Вносят кислый вкус и участвуют в энергетическом обмене (цикл Тринера)."
    }
  ]
}

{
